import itertools, subprocess

ROOT = '/private/tmp/live-spec-night18/wt-b'


def sizes(rev):
    out = subprocess.run(['git', 'ls-tree', '-r', '-l', rev], cwd=ROOT,
                         capture_output=True, text=True).stdout
    d = {}
    for line in out.splitlines():
        parts = line.split(None, 4)
        if len(parts) < 5 or parts[1] != 'blob':
            continue
        d[parts[4].strip()] = int(parts[3])
    return d


for rev in ('9efe559', 'HEAD'):
    S = sizes(rev)
    TARGET = 119116
    anchor = S.get('skills/spec-author/SKILL.md')
    print('===', rev, 'spec-author SKILL.md =', anchor)
    rest = TARGET - anchor
    cand = [(v, k) for k, v in S.items() if v <= rest and (
        k.endswith('SKILL.md') or k.startswith('skills/spec-author/')
        or k.startswith('templates/') or 'spec-format' in k
        or k in ('README.md', 'ARCHITECTURE.md', 'AGENTS.md', 'CLAUDE.md'))]
    hits = []
    for kk in (1, 2, 3):
        for combo in itertools.combinations(cand, kk):
            if sum(c[0] for c in combo) == rest:
                hits.append(combo)
        if hits:
            break
    print('need', rest, 'candidates', len(cand))
    for h in hits[:10]:
        print('   ', [(x[1], x[0]) for x in h])
    if not hits:
        print('    no exact 1-3 file combination')

